<?php
namespace App\Domain\WorkProcesses; use App\Domain\Homepage\HomepageCache; use App\Domain\PublicChrome\PublicChromeCache; use App\Models\{HomepageSection,NavigationItem}; use Illuminate\Support\Facades\Cache; use Throwable; final class WorkProcessCache { public static function version(int $id):int{try{return (int)Cache::rememberForever("public.work-processes.version.$id",fn()=>hrtime(true));}catch(Throwable){return hrtime(true);}} public static function indexVersion():int{try{return (int)Cache::rememberForever('public.work-processes.index.version',fn()=>hrtime(true));}catch(Throwable){return hrtime(true);}} public static function forget(int $id):void{try{Cache::put("public.work-processes.version.$id",hrtime(true));Cache::put('public.work-processes.index.version',hrtime(true));if(HomepageSection::where('work_process_id',$id)->exists())HomepageCache::forget();if(NavigationItem::where('work_process_id',$id)->exists())PublicChromeCache::forgetAll();}catch(Throwable){}} }
